package com.jobsprout.gateway.config;
import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.web.cors.reactive.CorsWebFilter; import org.springframework.web.cors.reactive.UrlBasedCorsConfigurationSource; import org.springframework.web.cors.CorsConfiguration; import java.util.List;
@Configuration public class CorsConfig { @Bean public CorsWebFilter corsWebFilter(){ CorsConfiguration c=new CorsConfiguration(); c.setAllowCredentials(true); c.setAllowedOriginPatterns(List.of("*")); c.setAllowedMethods(List.of("*")); c.setAllowedHeaders(List.of("*")); UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource(); s.registerCorsConfiguration("/**",c); return new CorsWebFilter(s); } }
